) AS (
  VALUES 
    (142::BIGINT, 'Explica muy claro, llevé el curso virtual y las evaluaciones fueron bastantes sencillas. La profe es un amor y siempre está anuente a dudas sobre la materia o los trabajos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, 'f0ef89c0f07a141b98161f459d9550f39137ec3c59ece69aab6a255e741c72fd'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Muy buena profe, hace las clases interactivas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'b8bddbc8c75f62de3c199508b86f180d03bb539308700a1b4ab2a43f417f7fcd'::TEXT, ARRAY[625]::BIGINT[]),
    (142::BIGINT, 'Si quiere aprender de verdad creo que no es la indicada, da como 10 minutos de explicación y en todo el tiempo restante lo manda a uno a "hablar" con los compañeros, el curso se pasa de manera fácil si ud sabe inglés, pero si no sabe busque mejores alternativas para aprender mejor.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'd584dcdf6c9fde1682f965fff394d74d5265b8888d9ffb24e2a58cc218a58019'::TEXT, ARRAY[625]::BIGINT[]),
    (142::BIGINT, 'Muy buena profe. Explica muy bien y hace las clases entretenidas. Califica muy suave. Recomiendo tener un buen grupo de trabajo, ya que hay varios trabajos en equipo. Aunque sacar 100 puede ser difícil, sí es posible. Siempre busca que el estudiante mejore. La recomiendo al 100%.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1d7d79b27a7b31339ec3c15a0c693c3148d9de0765a22038c284f75b06c73888'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Es un amor, explica bien aunque muy rápido, las presentaciones son bastante fáciles y no califica duro (pero cuesta sacarle un 100). Las clases son muy dinámicas y entretenidas y casi nunca duran las 3 horas, los quices y exámenes son sencillos, si no sabe inglés tal vez no sea la mejor opción'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '56a628ff59ca43fdfa5caf4973076a55392d28a7644d5da2dd412f0687dead22'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Buena profesora, con participar unas veces en cada clase y cumplir con los temas de cada semana vas bien, califica de una manera muy suave, explica bien y atiende dudas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'fe33b61618f235142dbdd99ba5277eed2abab91c35921d9273c2a20693e60868'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Es muy buena, es amable y comprensiva con los estudiantes. Deja todo claro, no es de esas típicas profesoras intensas. Califica suave, cuesta mucho sacarle un 100 en presentaciones orales, pero baja muy pocos puntos. Generalmente son decimales.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-01-30T00:00:00+00:00'::TIMESTAMPTZ, '4eaf984a54eaf8d4e4ee3c74de43b56634f26a785dd928259374bacff66854a0'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2024-12-27T00:00:00+00:00'::TIMESTAMPTZ, '7894d88f5b76932dd22eb47d35dac1d2510b481af8d40a65b427e9129b393e90'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Es una profe buena gente, con hacer todos lo trabajos se pasa bien. Hace algunas presentaciones como en todo curso de inglés, entonces si le cuesta inglés prepárese bien. El resto de evaluaciones son súper sencillas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Muchos proyectos grupales']::TEXT[], '2024-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'd14c0c4e78c2abd6111b73feb35ec689e685112ffcaad7c2b83c08dca56363bf'::TEXT, ARRAY[625]::BIGINT[]),
    (142::BIGINT, 'La profesora no enseña nada, asume que todo ya lo sabe, las clases son aburridas, lu único bueno son las actividades que hace en clase que algunas son vacilonas, espere muchas presentaciones grupales y siempre baja por algo alégrese si saca más de 90. Pero en lo demás revisa muy suave.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '7cd793732446d6d971829c7cf6f1b668d2b7f26ef87ce489b722e33ef98692fd'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Clases algo aburridas, califica normal, en general es una buena opcion'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, '059c2126d72a305d6c530b134134d6e44180c12170fa9122ccc7f87d6ca79239'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Da por un hecho que conoce temas de ingles, y a veces no es así, si usted lee en las presentaciones orales le va a caer muy mal, y aunque lo haga bien su nota en presentación oral no pasa de 90-95, cuando hay bastantes temas sus clases se hacen aburridas. No la recomiendo. Hay mejores opciones.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'a4708c2a46d5bc36a12fcd842c91b713641b7fff2e3901ca655e7e2f80946ccc'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'La profe es buenisima, si quiere aprender no dude que con ella lo hará'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'c9aa4f2b17b2719cb7e07d3cb237fdd8be8744ecdcb08cbbb5b2a6c4922c1d90'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'explica bien, sin embargo, me hizo un comentario respecto a que, si fuera por ella no me pasaba, porque no tengo un buen nivel de inglés, aún teniendo buena nota en el curso.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, '4fc81f74fef99be34fc1e6facf995afe407cf1df90a1751f2cafafb819c0c2b8'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Si quiere aprender inglés, con esta profesora va a lograr entender todos los temas. Es clara y concisa. Las actividades en clase son divertidas y los trabajos grupales son sencillos e ingeniosos. Ella es carismática y hace de la clase un entorno agradable. No se fija en pequeños errores.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'ed3e2fe0afa01d99a98842e66c4824da25cb1e14a46177182de2e41e56f1ed10'::TEXT, ARRAY[625]::BIGINT[]),
    (142::BIGINT, 'Es muy buena profe, siempre está dispuesta a ayudar y no califica duro. Deja tarea después de cada clase pero no demanda mucho tiempo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '03cb16e2a58f4e6a4ec0765b0f7bc2131f62f45d85ed8582d3e5000811bde70d'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Es una excelente profesora y persona, en todos los aspectos. Califica muy suave y si usted necesita aprender en inglés, de fijo aprende con ella. Si necesita ayuda, ella está dispuesta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, '923eecdbd5641f8ac141625bb2092dbd1f6d2e46479da413980b3e0dbed4c482'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '29e74144e020d2083038cd260c96f50c5cfc9d819bf604babc17da3e38ed780e'::TEXT, ARRAY[2433]::BIGINT[]),
    (142::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'bedb0f51f37cb57f852912dff29d8cce6891653cda0563d04c87cb2482bf958c'::TEXT, ARRAY[539]::BIGINT[]),
    (142::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-23T00:00:00+00:00'::TIMESTAMPTZ, '3ef1b648bb804affd42b1d49516ae861d975a12585c1c97ef24b65673466354d'::TEXT, ARRAY[625, 545]::BIGINT[]),
    (142::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '311872f530d9f33fa8c13cf6bb8b37efb78fe5764698adce79edf91e91671288'::TEXT, ARRAY[625, 545]::BIGINT[]),
    (142::BIGINT, 'Excelente profesora, es amable, respetuosa y ordenada. No califica duro, deja muy clara la materia y las tareas son sencillas, si quiere una clase tranquila y quiere aprender bien, sin duda matricule con ella!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '4280274e50eec58a343fb08c48935366618894ae23d6e5f618cd3af1b50e9cdd'::TEXT, ARRAY[539]::BIGINT[]),
    (142::BIGINT, 'Es una profesora muy organizada, deja tareas semanales que a veces son muy largas. En las clases toca hablar y practicar bastante, y hace las correcciones que debe hacer de manera respetuosa. Sin duda tomaría el curso con ella otra vez.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, '13aa06d88747c6f998f15607331be83c1aab67a30b1cd0159b40d1379824dc39'::TEXT, ARRAY[547]::BIGINT[]),
    (142::BIGINT, 'Deja trabajos semanales, que a veces quitan mucho tiempo y a veces no. Si uno va a clases puede aprender bastante porque le toca hablar, y la profe lo corrige a uno, pero si uno no va a clases no va a aprender nada.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '35a6359783c79aa587dc219301928bf7a90e969e15d1d31d9450177c5767c6e0'::TEXT, ARRAY[552]::BIGINT[]),
    (142::BIGINT, 'en modalidad virtual es super clara con las explicaciones y deja tareas que se pueden hacer en alrededor de una hora y son fáciles. es una muy buena opción para matricular'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '9eabb898d0c1824939aea906e3cfa21eda535d0a6a9104f4af8620da8a518b45'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Excelente profesora, súper simpatica, maneja muy bien la materia, se adapto excelentemente a la modalidad virtual, es bastante comprensible con los alumnos. Hace las clases interesantes, entretenidas y hasta dan ganas de asistir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '10c75c15802951e0d4ea7892749966de510be750594d6a77c9d18c8a0d677d78'::TEXT, ARRAY[552]::BIGINT[]),
    (142::BIGINT, 'No lo piense, matricule con ella, super accesible y comprensiva, evaluaciones fáciles y se hacen rápido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'c7228d8c9421b9c90f2a7e4d9eba384e562aa58548c54f901bd5ac10dc112166'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Muy buena profesora pero alarga mucho la clase.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'd5707c1b20fcb9049bbae500f51ca3d9c134d3bf80c77958a8753291132f1e86'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Le importa mucho la pronunciación. Deja bastantes laboratorios para la casa lo cual ayuda con la nota. Explica claro y es buena gente. Hace quices muy fáciles y divertidos en clase. Califica suave y es muy ordenada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'ffe5308e36f8406efb92ffaf4df572ff3f856131449b535e88aaa1cfce604567'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Clases excelentes']::TEXT[], '2019-01-09T00:00:00+00:00'::TIMESTAMPTZ, '38bf88cb68e90ecadada98d5bfa71430f00c2cbfdaa0c3247691fa6c8758738b'::TEXT, ARRAY[545]::BIGINT[]),
    (142::BIGINT, 'El curso es regalado, úselo de comodín para llenar +1 créditos en algún semestre. No se aprende lo que uno pensaría: se ve terminología de ingenierías, pero no tanto de mecatrónica en sí.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c92dcc6c1d4bbc8dff2097be4af536f5c6a852e7baee4f9abe615d4a0f7848a7'::TEXT, ARRAY[552]::BIGINT[]),
    (142::BIGINT, 'Excelente profesora, muy buena gente explica muy bien y hace la clase amena y entretenida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '7d7935d797682c7c2a43ffbdc2f8b7dfe56d18756faf2892bba7c72e9cf7b8b3'::TEXT, ARRAY[625]::BIGINT[]),
    (142::BIGINT, 'Muy buena profesora aunque alarga mucho las clases . La asistencia es muy importante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '7e48d168c6f475fd8cc0afb4d769d8f2635a9a238001267d85bc4acd1aaf78d9'::TEXT, ARRAY[625]::BIGINT[]),
