    (142::BIGINT, 'Muy buena profe, explica muy bien y trata de ayudar a los estudiantes que más les cuesta. Aveces puede ser un poco ruda evaluando. Yo la recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '24f8b554a2866ac4614aa1f9acc9c1defa5e69bef1f0b79a4e6cabeef9a25234'::TEXT, ARRAY[2433]::BIGINT[]),
